const byId: Record<string, AnkaraAvatar> = {};
for (const a of ANKARA_AVATARS) byId[a.id] = a;

export function avatarById(id: string | null | undefined): AnkaraAvatar {
  return (id && byId[id]) || UNKNOWN_AVATAR;
}

/** Pick a stable character for an opaque id (a speaker id, a session id). */
export function avatarFor(seed: string | null | undefined, offset = 0): AnkaraAvatar {
  if (!seed) return UNKNOWN_AVATAR;
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return ANKARA_AVATARS[(h + offset) % ANKARA_AVATARS.length];
}

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] as string);

/**
 * The prototype's avatarSVG(), with one change: `uid` makes the sprite's
 * internal mask id unique so two copies of the same character on one screen
 * do not collide.
 */
export function avatarSVG(a: AnkaraAvatar, size: number, uid: string): string {
  if (a.svg) {
    const unique = a.svg.replace(new RegExp(`vm-${a.id}\\b`, "g"), `vm-${a.id}-${uid}`);
    return unique.replace("<svg ", `<svg width="${size}" height="${size}" role="img" aria-label="${esc(a.name)}" `);
  }
  return `<svg viewBox="0 0 64 64" width="${size}" height="${size}" role="img" aria-label="${esc(a.name)}"><circle cx="32" cy="32" r="32" fill="${a.bg}"/>${a.body}</svg>`;
}
